#include "sobol_cpu.hpp"

#include <bit>

#if defined(_MSC_VER)
#pragma warning(push, 0)
#endif
#include "sobol_kernel.cpp"   // generated by slangc into the build tree
#if defined(_MSC_VER)
#pragma warning(pop)
#endif

namespace ohao::sampling {

std::array<float, 4> sobolGroup(uint32_t index, uint32_t seed, uint32_t group) {
    Vector<uint32_t, 4> io[2]{};
    io[0].x = index;
    io[0].y = seed;
    io[0].z = group;
    GlobalParams_0 globals{};
    globals.io_0.data = io;
    globals.io_0.count = 2;
    ComputeVaryingInput range{};
    range.startGroupID = {0, 0, 0};
    range.endGroupID = {1, 1, 1};
    ::run(&range, nullptr, &globals);
    return {std::bit_cast<float>(io[1].x), std::bit_cast<float>(io[1].y), std::bit_cast<float>(io[1].z),
            std::bit_cast<float>(io[1].w)};
}

} // namespace ohao::sampling
